// Builds src/contract/bindings/index.ts from the files ts-rs generated.
import { readdirSync, writeFileSync } from "node:fs";
const dir = new URL("../src/contract/bindings/", import.meta.url);
const names = readdirSync(dir)
  .filter((f) => f.endsWith(".ts") && f !== "index.ts")
  .map((f) => f.slice(0, -3))
  .sort();
writeFileSync(
  new URL("index.ts", dir),
  "// Generated by `pnpm gen:types`. Do not edit.\n" +
    names.map((n) => `export type { ${n} } from "./${n}";`).join("\n") +
    "\n",
);
console.log(`bindings index: ${names.length} types`);
